const value = $json.output;
let data;
try {
  data = typeof value === 'string' ? JSON.parse(value) : value;
} catch {
  data = null;
}
const fail = (message, validationError) => [{ json: { ready: false, decision: 'ERROR', intentRunId: '', actionType: '', recipient: '', subject: '', body: '', message, validationError } }];
if (!data || typeof data !== 'object' || Array.isArray(data)) return fail('I could not create a valid email request. Please try again.', 'Structured agent output was missing.');
const message = typeof data.message === 'string' && data.message.trim() ? data.message.trim() : 'Please provide the missing email details.';
if (data.ready !== true) return [{ json: { ready: false, decision: data.decision === 'NEEDS_INPUT' ? 'NEEDS_INPUT' : 'ERROR', intentRunId: '', actionType: '', recipient: '', subject: '', body: '', message } }];
const intentRunId = typeof data.intentRunId === 'string' ? data.intentRunId.trim() : '';
const actionType = typeof data.actionType === 'string' ? data.actionType.trim() : '';
const recipient = typeof data.recipient === 'string' ? data.recipient.trim() : '';
const subject = typeof data.subject === 'string' ? data.subject.trim() : '';
const body = typeof data.body === 'string' ? data.body.trim() : '';
const decision = typeof data.decision === 'string' ? data.decision.toUpperCase() : '';
if (!intentRunId || actionType !== 'email.send' || !['ALLOW', 'DENY', 'REQUIRE_APPROVAL'].includes(decision)) return fail('Guardian authorization could not be verified. No email was sent.', 'Missing or invalid Guardian authorization identity.');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(recipient) || !subject || !body) return fail('The email details were invalid. No email was sent.', 'Recipient, subject, or body failed validation.');
return [{ json: { ready: true, decision, intentRunId, actionType, recipient, subject, body, message } }];
